static bool _tu_rest(string where)
{
    var me = BuddyCron.Core.Player;
    var now = System.DateTime.Now;
    if (me == null || me.IsDead || me.InCombat || me.IsLooting) { _tu_on = false; return false; }
    var comp = me.Companion;
    if (comp != null && comp.IsDead) { _tu_on = false; return false; }
    if (!_tu_on)
    {
        bool need = me.HealthPercent < 95f || (comp != null && comp.HealthPercent < 90f);
        if (!need || (now - _tu_fail).TotalSeconds < 20) return false;
        _tu_on = true; _tu_start = now;
        Reborn.Utilities.Logging.Write("[Rest] Resting to full before " + where);
    }
    bool full = me.HealthPercent >= 99f && (comp == null || comp.HealthPercent >= 98f);
    if (full || (now - _tu_start).TotalSeconds > 20)
    {
        if (!full) _tu_fail = now;
        _tu_on = false;
        if (me.IsCasting) BuddyCron.Managers.AbilityManager.StopCasting();
        return false;
    }
    if (me.IsMoving) { BuddyCron.Navigation.Navigator.PlayerMover.MoveStop(); return true; }
    if (me.IsCasting) return true;
    if (_tu_name == null)
        foreach (var n in _tu_names) { if (BuddyCron.Managers.AbilityManager.CanCast(n, me).Success) { _tu_name = n; break; } }
    if (_tu_name != null && BuddyCron.Managers.AbilityManager.Cast(_tu_name, me).Success) return true;
    if ((now - _tu_start).TotalSeconds < 4) return true;
    _tu_on = false; _tu_fail = now;
    Reborn.Utilities.Logging.Write("[Rest] Could not start resting, going on");
    return false;
}

